// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @notice Minimal ERC-8004 agent identity interface.
interface IIdentityRegistry {
    /// @notice Returns the agent NFT owner; unknown IDs revert.
    function ownerOf(uint256 agentId) external view returns (address);

    /// @notice Returns the agent's registered execution wallet.
    function getAgentWallet(uint256 agentId) external view returns (address);
}

/// @title ArcPay Automated Vault
/// @notice Per-depositor ERC-20 USDC custody with manual and agent-triggered payroll.
/// @dev Intended for Arc Testnet USDC (0x3600000000000000000000000000000000000000,
/// six decimals) and IdentityRegistry (0x8004A818BFB912233c491871b3d84c89A494BD9e).
/// All amounts are ERC-20 base units; native currency is never accepted or used.
/// Failed recipient transfers return the failed amount to the payer's vault balance;
/// other payments proceed and payroll runs still advance their schedule.
/// Designed for standard USDC, not fee-on-transfer or rebasing tokens.
contract ArcPayVault is Pausable, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_BATCH_SIZE = 50;
    uint64 public constant MIN_INTERVAL = 60 seconds;

    IERC20 public immutable usdc;
    IIdentityRegistry public immutable identityRegistry;

    mapping(address => uint256) public vaultBalance;
    /// @notice Total outstanding depositor liabilities, not cumulative deposits.
    uint256 public totalDeposits;
    uint256 public batchCounter;

    struct Payroll {
        address[] recipients;
        uint256[] amounts;
        uint64 interval;
        uint64 nextExecutionAt;
        uint256 maxPerRun;
        uint256 agentId;
        uint32 runs;
        bool active;
    }

    mapping(address => Payroll) private _payrolls;

    error ZeroAddress();
    error ZeroAmount();
    error EmptyBatch();
    error ArrayLengthMismatch(uint256 recipientsLength, uint256 amountsLength);
    error BatchTooLarge(uint256 length, uint256 maximum);
    error InvalidRecipient(uint256 index, address recipient);
    error InvalidPaymentAmount(uint256 index);
    error PaymentTotalOverflow();
    error InsufficientVaultBalance(uint256 available, uint256 required);
    error IntervalTooShort(uint64 interval, uint64 minimum);
    error AgentNotRegistered(uint256 agentId);
    error PayrollInactive(address payer);
    error PayrollNotDue(uint64 nextExecutionAt);
    error OverMaxPerRun(uint256 total, uint256 maximum);
    error NotAuthorizedAgent(uint256 agentId, address caller);
    error TimestampOverflow();
    error RunCounterExhausted(address payer);
    error RenounceDisabled();

    event Deposited(address indexed account, uint256 amount, uint256 newBalance);
    event Withdrawn(address indexed account, uint256 amount, uint256 newBalance);
    event BatchPaid(address indexed payer, uint256 indexed batchId, uint256 recipientCount, uint256 total);
    event Paid(address indexed payer, address indexed recipient, uint256 amount, uint256 indexed batchId);
    event PayrollConfigured(
        address indexed payer,
        uint256 indexed agentId,
        uint256 recipientCount,
        uint256 total,
        uint64 interval,
        uint256 maxPerRun
    );
    event PayrollCancelled(address indexed payer);
    event PayrollExecuted(
        address indexed payer,
        uint256 indexed agentId,
        address indexed executor,
        uint32 runId,
        uint256 total,
        uint256 recipientCount
    );
    event PayrollPaid(address indexed payer, address indexed recipient, uint256 amount, uint32 indexed runId);
    event PaymentFailed(address indexed payer, address indexed recipient, uint256 amount);

    /// @notice Creates the vault with an ERC-20 token, ERC-8004 registry and admin.
    /// @dev Zero initialOwner is rejected by Ownable with OwnableInvalidOwner.
    /// @param usdc_ ERC-20 USDC address; use Arc Testnet's USDC address on Arc.
    /// @param identityRegistry_ ERC-8004 identity registry address.
    /// @param initialOwner Address authorized to pause and unpause.
    constructor(address usdc_, address identityRegistry_, address initialOwner) Ownable(initialOwner) {
        if (usdc_ == address(0) || identityRegistry_ == address(0)) revert ZeroAddress();
        usdc = IERC20(usdc_);
        identityRegistry = IIdentityRegistry(identityRegistry_);
    }

    /// @notice Deposits approved ERC-20 USDC into the caller's own balance.
    /// @param amount Positive amount in USDC base units (six decimals on Arc).
    function deposit(uint256 amount) external whenNotPaused nonReentrant {
        if (amount == 0) revert ZeroAmount();
        usdc.safeTransferFrom(msg.sender, address(this), amount);
        vaultBalance[msg.sender] += amount;
        totalDeposits += amount;
        emit Deposited(msg.sender, amount, vaultBalance[msg.sender]);
    }

    /// @notice Withdraws the caller's USDC; remains available while paused.
    /// @param amount Positive amount in USDC base units.
    function withdraw(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        _debit(msg.sender, amount);
        usdc.safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount, vaultBalance[msg.sender]);
    }

    /// @notice Pays up to MAX_BATCH_SIZE recipients from the caller's balance.
    /// @dev Failed transfers return the failed amount to the payer's vault balance.
    /// @param recipients Nonzero recipient addresses other than this vault.
    /// @param amounts Positive USDC base-unit amounts matching recipients.
    function batchPay(address[] calldata recipients, uint256[] calldata amounts)
        external whenNotPaused nonReentrant
    {
        uint256 total = _validatePayments(recipients, amounts);
        _debit(msg.sender, total);
        uint256 batchId = ++batchCounter;
        total = 0;
        uint256 successfulCount;
        for (uint256 i; i < recipients.length; ++i) {
            if (_tryPay(msg.sender, recipients[i], amounts[i])) {
                total += amounts[i];
                ++successfulCount;
                emit Paid(msg.sender, recipients[i], amounts[i], batchId);
            }
        }
        emit BatchPaid(msg.sender, batchId, successfulCount, total);
    }

    /// @notice Creates or replaces the caller's payroll, with its first run due immediately.
    /// @dev No funds are reserved. The current registry owner or agent wallet may execute.
    /// @param recipients At most MAX_BATCH_SIZE nonzero recipients, excluding the vault.
    /// @param amounts Positive USDC base-unit amounts matching recipients.
    /// @param interval Minimum time between executions, at least MIN_INTERVAL.
    /// @param maxPerRun Upper bound on the total USDC paid per execution.
    /// @param agentId Registered ERC-8004 agent authorized for this payroll.
    function setPayroll(
        address[] calldata recipients,
        uint256[] calldata amounts,
        uint64 interval,
        uint256 maxPerRun,
        uint256 agentId
    ) external whenNotPaused nonReentrant {
        uint256 total = _validatePayments(recipients, amounts);
        if (interval < MIN_INTERVAL) revert IntervalTooShort(interval, MIN_INTERVAL);
        if (total > maxPerRun) revert OverMaxPerRun(total, maxPerRun);
        if (!_isAgentRegistered(agentId)) revert AgentNotRegistered(agentId);
        if (block.timestamp > type(uint64).max) revert TimestampOverflow();

        Payroll storage payroll = _payrolls[msg.sender];
        delete payroll.recipients;
        delete payroll.amounts;
        payroll.recipients = recipients;
        payroll.amounts = amounts;
        payroll.interval = interval;
        payroll.nextExecutionAt = uint64(block.timestamp);
        payroll.maxPerRun = maxPerRun;
        payroll.agentId = agentId;
        payroll.runs = 0;
        payroll.active = true;
        emit PayrollConfigured(msg.sender, agentId, recipients.length, total, interval, maxPerRun);
    }

    /// @notice Cancels the caller's active payroll, including while paused.
    function cancelPayroll() external nonReentrant {
        Payroll storage payroll = _payrolls[msg.sender];
        if (!payroll.active) revert PayrollInactive(msg.sender);
        payroll.active = false;
        emit PayrollCancelled(msg.sender);
    }

    /// @notice Returns the full payroll configuration and execution state for a payer.
    function getPayroll(address payer) external view returns (Payroll memory) {
        return _payrolls[payer];
    }

    /// @notice Whether a nonzero address is the agent NFT owner or registered agent wallet.
    /// @dev Each registry lookup is independently protected against registry reverts.
    function isAgentOperator(uint256 agentId, address who) public view returns (bool) {
        if (who == address(0)) return false;
        try identityRegistry.ownerOf(agentId) returns (address agentOwner) {
            if (agentOwner == who) return true;
        } catch {}
        try identityRegistry.getAgentWallet(agentId) returns (address agentWallet) {
            if (agentWallet == who) return true;
        } catch {}
        return false;
    }

    /// @notice Evaluates payroll rules in priority order, without checking the caller.
    /// @return executable Whether all payroll rules currently pass.
    /// @return reason First failing rule, or "OK".
    function checkPayroll(address payer) public view returns (bool executable, string memory reason) {
        if (paused()) return (false, "PAUSED");
        Payroll storage payroll = _payrolls[payer];
        if (!payroll.active) return (false, "PAYROLL_INACTIVE");
        if (!_isAgentRegistered(payroll.agentId)) return (false, "AGENT_NOT_REGISTERED");
        if (block.timestamp < payroll.nextExecutionAt) return (false, "NOT_DUE");
        uint256 total = _payrollTotal(payroll);
        if (total > payroll.maxPerRun) return (false, "OVER_MAX_PER_RUN");
        if (total > vaultBalance[payer]) return (false, "INSUFFICIENT_BALANCE");
        return (true, "OK");
    }

    /// @notice Lets the configured ERC-8004 agent owner or wallet execute a due payroll.
    /// @dev All rules precede accounting and transfers. No catch-up runs are allowed.
    /// Failed transfers return the failed amount to the payer's vault balance; the run is consumed.
    /// @param payer Depositor whose configured payroll and balance should be used.
    function executePayroll(address payer) external whenNotPaused nonReentrant {
        Payroll storage payroll = _payrolls[payer];
        if (!payroll.active) revert PayrollInactive(payer);
        uint256 agentId = payroll.agentId;
        if (!_isAgentRegistered(agentId)) revert AgentNotRegistered(agentId);
        if (block.timestamp < payroll.nextExecutionAt) revert PayrollNotDue(payroll.nextExecutionAt);
        uint256 total = _payrollTotal(payroll);
        if (total > payroll.maxPerRun) revert OverMaxPerRun(total, payroll.maxPerRun);
        uint256 available = vaultBalance[payer];
        if (total > available) revert InsufficientVaultBalance(available, total);
        if (!isAgentOperator(agentId, msg.sender)) revert NotAuthorizedAgent(agentId, msg.sender);
        if (block.timestamp > uint256(type(uint64).max) - payroll.interval) revert TimestampOverflow();
        if (payroll.runs == type(uint32).max) revert RunCounterExhausted(payer);

        _debit(payer, total);
        payroll.nextExecutionAt = uint64(block.timestamp + payroll.interval);
        uint32 runId = ++payroll.runs;
        uint256 count = payroll.recipients.length;
        total = 0;
        uint256 successfulCount;
        for (uint256 i; i < count; ++i) {
            address recipient = payroll.recipients[i];
            uint256 amount = payroll.amounts[i];
            if (_tryPay(payer, recipient, amount)) {
                total += amount;
                ++successfulCount;
                emit PayrollPaid(payer, recipient, amount, runId);
            }
        }
        emit PayrollExecuted(payer, agentId, msg.sender, runId, total, successfulCount);
    }

    /// @notice Pauses deposits, manual batches, payroll configuration and execution.
    /// @dev Withdrawals and payroll cancellation remain available.
    function pause() public onlyOwner {
        _pause();
    }

    /// @notice Resumes deposits, manual batches, payroll configuration and execution.
    function unpause() public onlyOwner {
        _unpause();
    }

    function renounceOwnership() public view override onlyOwner {
        revert RenounceDisabled();
    }

    function _tryPay(address payer, address recipient, uint256 amount) private returns (bool ok) {
        try usdc.transfer(recipient, amount) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        if (!ok) {
            vaultBalance[payer] += amount;
            totalDeposits += amount;
            emit PaymentFailed(payer, recipient, amount);
        }
    }

    function _debit(address payer, uint256 amount) private {
        uint256 available = vaultBalance[payer];
        if (amount > available) revert InsufficientVaultBalance(available, amount);
        vaultBalance[payer] = available - amount;
        totalDeposits -= amount;
    }

    function _validatePayments(address[] calldata recipients, uint256[] calldata amounts)
        private view returns (uint256 total)
    {
        uint256 count = recipients.length;
        if (count == 0) revert EmptyBatch();
        if (count != amounts.length) revert ArrayLengthMismatch(count, amounts.length);
        if (count > MAX_BATCH_SIZE) revert BatchTooLarge(count, MAX_BATCH_SIZE);
        for (uint256 i; i < count; ++i) {
            if (recipients[i] == address(0) || recipients[i] == address(this)) {
                revert InvalidRecipient(i, recipients[i]);
            }
            uint256 amount = amounts[i];
            if (amount == 0) revert InvalidPaymentAmount(i);
            if (amount > type(uint256).max - total) revert PaymentTotalOverflow();
            total += amount;
        }
    }

    function _payrollTotal(Payroll storage payroll) private view returns (uint256 total) {
        // Only setPayroll writes these arrays; validation caps their length at 50
        // and ensures the total fits uint256.
        for (uint256 i; i < payroll.amounts.length; ++i) {
            total += payroll.amounts[i];
        }
    }

    function _isAgentRegistered(uint256 agentId) private view returns (bool) {
        try identityRegistry.ownerOf(agentId) returns (address) {
            return true;
        } catch {
            return false;
        }
    }
}

